int pa[N];

int find(int x){
    if(x==pa[x]){
        return x;
    }
    return pa[x]=find(pa[x]);
}

void merge(int x,int y){
    int rx=find(x),ry=find(y);
    if(rx!=ry){
        pa[rx]=ry;
    }
}

int n,m,op,x,k,y;
int a[N],c[N];

int lowbit(int x){
    return x&(-x);
}

void add(int i,int k){
    while(i<=n){
        c[i]+=k;
        i+=lowbit(i);
    }
}

int sum(int i){
    int s=0;
    while(i){
        s+=c[i];
        i-=lowbit(i);
    }
    return s;
}

int n,m,a,l,r;
int dp[N][20];

void ST(){
    for(int j=1;j<=log2(n);j++){
        for(int i=1;i<=n-(1<<j)+1;i++){
            dp[i][j]=max(dp[i][j-1],dp[i+(1<<(j-1))][j-1]);
        }
    }
}

int RMQ(int l,int r){
    int k=log2(r-l+1);
    int t=max(dp[l][k],dp[r-(1<<k)+1][k]);
    return t;
}
